def check(N, M, Edges):
    from collections import defaultdict

    # Create adjacency list
    graph = defaultdict(list)
    for u, v in Edges:
        graph[u].append(v)
        graph[v].append(u)

    def is_hamiltonian_path(path, visited):
        if len(path) == N:
            return True

        last_vertex = path[-1]
        for neighbor in graph[last_vertex]:
            if not visited[neighbor]:
                visited[neighbor] = True
                path.append(neighbor)
                if is_hamiltonian_path(path, visited):
                    return True
                path.pop()
                visited[neighbor] = False
        return False

    for start in range(1, N + 1):
        visited = [False] * (N + 1)
        visited[start] = True
        if is_hamiltonian_path([start], visited):
            return True
    return False
